INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','mcq','Which class of antihypertensive drugs acts by inhibiting the conversion of angiotensin I to angiotensin II?','["A. Calcium channel blockers","B. Beta-blockers","C. Angiotensin receptor blockers","D. ACE inhibitors"]','D','ACE inhibitors (e.g., lisinopril, enalapril) block angiotensin-converting enzyme, preventing formation of angiotensin II from angiotensin I, reducing vasoconstriction and aldosterone secretion. A: CCBs block L-type calcium channels. C: ARBs block AT1 receptors directly. D: Beta-blockers reduce cardiac output and renin release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','mcq','A patient on hydrochlorothiazide develops low serum potassium and elevated uric acid. Which electrolyte disturbance is most commonly associated with thiazide diuretics?','["A. Hyperkalemia","B. Hyponatremia","C. Hypokalemia","D. Hypocalcemia"]','C','Thiazide diuretics increase sodium and water excretion leading to potassium loss (hypokalemia) and uric acid retention. A: Thiazides cause hypokalemia, not hyperkalemia. B: Hyponatremia can occur but is less prominent. D: Thiazides decrease calcium excretion (hypercalcemia, not hypocalcemia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','mcq','Which antihypertensive drug class is contraindicated in bilateral renal artery stenosis due to risk of acute kidney injury?','["A. Calcium channel blockers","B. Thiazide diuretics","C. Beta-blockers","D. ACE inhibitors"]','D','ACE inhibitors block angiotensin II-mediated efferent arteriole constriction. In bilateral renal artery stenosis, GFR is maintained by high angiotensin II tone; ACE inhibition removes this, precipitating AKI. A: CCBs are safe. B: Thiazides do not affect glomerular hemodynamics. C: Beta-blockers are not contraindicated here.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','mcq','A 58-year-old man with hypertension and stable COPD requires antihypertensive therapy. Which beta-blocker is most appropriate if beta-blockade is necessary?','["A. Propranolol","B. Carvedilol","C. Metoprolol","D. Nadolol"]','C','Metoprolol is a cardioselective (beta-1 selective) blocker with less beta-2 blockade, reducing bronchoconstriction risk. A: Propranolol is non-selective and contraindicated in COPD/asthma. B: Carvedilol blocks alpha-1, beta-1, beta-2 and should be avoided. D: Nadolol is non-selective and contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','mcq','A 45-year-old woman develops a dry, persistent cough after starting an antihypertensive. The cough is attributed to accumulation of which substance?','["A. Angiotensin II","B. Bradykinin","C. Aldosterone","D. Renin"]','B','ACE inhibitors block the degradation of bradykinin (normally broken down by ACE/kininase II), causing bradykinin accumulation in the airways — a dry cough in 10-15% of patients. A: Angiotensin II is reduced. C: Aldosterone decreases. D: Renin increases reflexively but does not cause cough.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','mcq','A hypertensive patient with a history of angioedema on lisinopril requires a change. Which class is the most appropriate RAAS-blocking alternative?','["A. Thiazide diuretics","B. Calcium channel blockers","C. Angiotensin receptor blockers","D. Loop diuretics"]','C','ARBs (e.g., losartan) block AT1 receptors and do not affect bradykinin metabolism, so they do not cause ACE inhibitor-related cough or angioedema. A and D: Diuretics do not block the RAAS. B: CCBs act on calcium channels, not the RAAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','mcq','Amlodipine belongs to which CCB subclass, and what is its primary vascular effect?','["A. Phenylalkylamine; decreases heart rate","B. Benzothiazepine; decreases AV conduction","C. Dihydropyridine; causes peripheral vasodilation","D. Dihydropyridine; negative inotropic effect"]','C','Amlodipine is a dihydropyridine CCB acting predominantly on vascular smooth muscle L-type calcium channels, causing peripheral vasodilation and reduced afterload. A: Verapamil (phenylalkylamine) is rate-reducing. B: Diltiazem (benzothiazepine) slows AV conduction. D: Dihydropyridines have minimal cardiac effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','mcq','A 62-year-old man with hypertension, type 2 diabetes, and microalbuminuria starts antihypertensive therapy. Which drug provides the most renoprotective benefit?','["A. Amlodipine","B. Hydrochlorothiazide","C. Lisinopril","D. Metoprolol"]','C','ACE inhibitors such as lisinopril are first-line in diabetic nephropathy. They reduce intraglomerular pressure by dilating efferent arterioles (via reduced angiotensin II), decreasing proteinuria and slowing CKD progression. A: CCBs lower BP but lack specific renoprotective effects. B: Thiazides are not preferred with low GFR. D: Beta-blockers have no established renoprotective benefit in diabetic nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','mcq','A 70-year-old woman is prescribed spironolactone for resistant hypertension. Which serious adverse effect requires electrolyte monitoring?','["A. Hypokalemia","B. Hyperkalemia","C. Hyponatremia","D. Hypercalcemia"]','B','Spironolactone is an aldosterone receptor antagonist (potassium-sparing diuretic). Blocking aldosterone reduces potassium excretion, leading to hyperkalemia — potentially life-threatening. A: Hypokalemia is seen with loop or thiazide diuretics. C: Hyponatremia is less prominent. D: Hypercalcemia is not associated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','mcq','A pregnant woman at 20 weeks gestation presents with severe hypertension. Which antihypertensive is absolutely contraindicated due to teratogenicity?','["A. Methyldopa","B. Labetalol","C. Nifedipine","D. Lisinopril"]','D','ACE inhibitors and ARBs are absolutely contraindicated in pregnancy — they cause fetal renal dysgenesis, oligohydramnios, skull hypoplasia, and neonatal death (FDA category D). A: Methyldopa is the safest antihypertensive in pregnancy. B: Labetalol is used for pregnancy-related hypertension. C: Nifedipine is used for acute severe hypertension in pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','mcq','Which Vaughan-Williams class primarily blocks sodium channels to reduce the rate of rise of the cardiac action potential (phase 0)?','["A. Class I","B. Class II","C. Class III","D. Class IV"]','A','Class I antiarrhythmics block voltage-gated Na+ channels, slowing phase 0 depolarization. Subdivided into IA (moderate), IB (fast), IC (slow) dissociation. B: Class II are beta-blockers. C: Class III block K+ channels prolonging repolarization. D: Class IV are calcium channel blockers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','mcq','Amiodarone is classified as Class III. What is its primary mechanism?','["A. Sodium channel blockade","B. Calcium channel blockade","C. Beta-adrenergic receptor blockade","D. Potassium channel blockade prolonging repolarization"]','D','Amiodarone primarily blocks K+ channels, prolonging the action potential duration and effective refractory period (phase 3). It also has class I, II, and IV properties. A: Na+ channel blockade is class I. C: Beta-blockade is class II (amiodarone has this as a secondary effect). D: Ca2+ channel blockade is class IV (secondary).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','mcq','Which antiarrhythmic is given IV for acute SVT by transiently blocking AV nodal conduction?','["A. Lidocaine","B. Flecainide","C. Quinidine","D. Adenosine"]','D','Adenosine activates A1 receptors in the AV node, hyperpolarizing it and transiently blocking conduction to terminate reentrant SVT. Its half-life is <10 seconds. A: Lidocaine acts on ventricular Na+ channels and is not used for SVT. C: Quinidine is class IA oral agent. D: Flecainide is class IC, not used acutely for SVT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','mcq','A patient on quinidine develops torsades de pointes. Which electrophysiologic change predisposes to this arrhythmia?','["A. Shortened QRS duration","B. Prolonged QT interval","C. Shortened PR interval","D. Increased phase 4 depolarization slope"]','B','Quinidine (Class IA) blocks K+ channels in addition to Na+ channels, prolonging the action potential and QT interval. QT prolongation predisposes to early afterdepolarizations and torsades de pointes. A: QRS widens (not shortens). C: PR interval is prolonged. D: Phase 4 slope is decreased.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','mcq','Lidocaine (Class IB) is preferentially used for ventricular arrhythmias. Why is it ineffective for atrial arrhythmias?','["A. It prolongs atrial refractoriness","B. Atrial cells have a shorter action potential less affected by Class IB drugs","C. It blocks the AV node","D. It enhances vagal tone"]','B','Class IB drugs (lidocaine, mexiletine) preferentially act on depolarized or rapidly firing tissue. Atrial cells have a shorter action potential and recover faster from inactivation, making them less susceptible. A: Lidocaine does not significantly affect atrial refractoriness. C: Lidocaine does not block the AV node. D: Lidocaine has no vagal effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','mcq','A patient with AF and no structural heart disease is started on flecainide. Why is flecainide contraindicated in structural heart disease?','["A. It has potent negative inotropic and proarrhythmic effects in diseased myocardium","B. It causes severe bradycardia in diseased hearts","C. It prolongs the QT interval excessively in ischemic tissue","D. It is metabolized to a toxic compound in heart failure"]','A','Class IC drugs show prominent Na+ channel blockade even at normal rates. In structurally diseased hearts (ischemia, HF, LVH), this proarrhythmic effect can precipitate life-threatening ventricular arrhythmias (demonstrated in CAST trial). A: Bradycardia is not the primary concern. C: QT prolongation is class IA/III. D: Not the mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','mcq','A patient on long-term amiodarone develops progressive dyspnea and bilateral pulmonary infiltrates on CXR. What is the most likely cause?','["A. Amiodarone-induced thyrotoxicosis","B. Pulmonary toxicity from amiodarone","C. Amiodarone-induced hepatotoxicity","D. Corneal microdeposits"]','B','Pulmonary toxicity (pneumonitis/fibrosis) is the most serious adverse effect of amiodarone, in 5-15% of patients on long-term therapy: progressive dyspnea, dry cough, bilateral infiltrates. A: Thyroid dysfunction is common but does not cause pulmonary infiltrates. C: Hepatotoxicity presents with elevated LFTs. D: Corneal deposits cause visual halos, not pulmonary symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','mcq','A 55-year-old post-MI patient develops hemodynamically stable sustained ventricular tachycardia. Which agent is drug of choice?','["A. Digoxin","B. Verapamil","C. Adenosine","D. Amiodarone"]','D','Amiodarone is the drug of choice for hemodynamically stable VT with its multi-class antiarrhythmic properties. A: Digoxin is not used for VT. B: Verapamil can worsen hemodynamics in VT and is dangerous in WPW-associated VT. C: Adenosine is for SVT, not VT (can precipitate VF).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','mcq','Which antiarrhythmic causes a lupus-like syndrome, and which metabolite mediates this?','["A. Procainamide; N-acetylprocainamide (NAPA)","B. Quinidine; 3-hydroxyquinidine","C. Lidocaine; monoethylglycinexylidide (MEGX)","D. Disopyramide; mono-N-dealkyldisopyramide"]','A','Procainamide is acetylated in the liver to NAPA. Procainamide itself (not NAPA) causes a lupus-like syndrome (ANA in 50-80%, symptomatic lupus in 20-30%), reversible on stopping. NAPA has class III activity. A: Quinidine causes cinchonism. C: MEGX is a lidocaine metabolite not causing lupus. D: Disopyramide causes anticholinergic effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','mcq','Verapamil and diltiazem are Class IV antiarrhythmics. Which cardiac tissue is their primary target?','["A. Ventricular myocardium","B. Purkinje fibers","C. Sinoatrial and atrioventricular nodes","D. Bundle of His"]','C','Class IV CCBs block L-type Ca2+ channels predominantly in SA and AV nodes, where depolarization is calcium-dependent. This slows heart rate and AV conduction. A: Ventricular myocardium is predominantly Na+-dependent. B: Purkinje fibers are Na+-dependent. D: Bundle of His is Na+-dependent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','mcq','Digoxin improves cardiac contractility in heart failure through which mechanism?','["A. Activation of beta-1 adrenergic receptors","B. Activation of cyclic AMP","C. Blockade of L-type calcium channels","D. Inhibition of Na+/K+-ATPase pump"]','D','Digoxin inhibits Na+/K+-ATPase, increasing intracellular Na+, which reduces Na+/Ca2+ exchanger activity, leading to increased intracellular Ca2+ and positive inotropy. A: Digoxin does not activate beta-1 receptors. C: Digoxin indirectly increases Ca2+ but does not block CCBs. D: Digoxin does not act via cAMP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','mcq','Which drug class reduces mortality in systolic HF by blocking maladaptive RAAS activation?','["A. Loop diuretics","B. Digoxin","C. ACE inhibitors","D. Dobutamine"]','C','ACE inhibitors reduce angiotensin II and aldosterone, decreasing preload and afterload and attenuating cardiac remodeling, reducing mortality in HFrEF. A: Loop diuretics reduce symptoms but not mortality. B: Digoxin reduces hospitalizations but not mortality. D: Dobutamine is a short-term inotrope without long-term mortality benefit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','mcq','Which diuretic is most commonly used for symptom relief in acute decompensated heart failure?','["A. Hydrochlorothiazide","B. Spironolactone","C. Furosemide","D. Acetazolamide"]','C','Furosemide inhibits the Na+/K+/2Cl- cotransporter in the thick ascending limb, producing rapid potent diuresis relieving pulmonary congestion and peripheral edema. A: Thiazides are less potent and ineffective at low GFR. B: Spironolactone is for chronic HF mortality benefit. D: Acetazolamide has limited use in HF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','mcq','A patient with HFrEF is prescribed carvedilol. Why is it important to start at a low dose and uptitrate slowly?','["A. Carvedilol requires hepatic activation","B. Carvedilol causes severe hyperkalemia at full doses","C. Abrupt full-dose beta-blockade can acutely worsen cardiac function in decompensated HF","D. High doses cause QT prolongation"]','C','In HFrEF, the heart depends on sympathetic drive. Starting at full doses can abruptly remove this compensatory mechanism, precipitating acute decompensation. Slow uptitration allows adaptation. A: Carvedilol is not a prodrug. C: Hyperkalemia is not carvedilol-specific. D: Carvedilol does not significantly prolong QT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','mcq','A 68-year-old with HFrEF intolerant of ACE inhibitors is placed on hydralazine + isosorbide dinitrate. What is the mechanism?','["A. Hydralazine reduces preload; isosorbide dinitrate reduces afterload","B. Hydralazine reduces afterload (arterial vasodilation);('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','mcq','Ivabradine is used as adjunct in HFrEF with persistent HR >70 bpm despite optimal beta-blocker therapy. What is its mechanism?','["A. Blocks L-type calcium channels in the SA node","B. Increases vagal tone to the SA node","C. Blocks beta-1 adrenergic receptors in the SA node","D. Inhibits the funny current (If) in the SA node"]','D','Ivabradine specifically inhibits the HCN channel (funny current, If) in the SA node, reducing the pacemaker slope of phase 4 depolarization and slowing heart rate without affecting contractility. A: That is verapamil/diltiazem. C: That is beta-blocker mechanism. D: Ivabradine does not affect the autonomic nervous system.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','mcq','A 72-year-old on digoxin presents with nausea, yellow-green visual halos, and bradycardia. Serum K+ = 2.9 mEq/L. What potentiates digoxin toxicity?','["A. Hyperkalemia competes with digoxin for Na+/K+-ATPase binding","B. Hypokalemia increases digoxin binding to Na+/K+-ATPase","C. Hypokalemia decreases digoxin renal clearance","D. Low potassium reduces digoxin volume of distribution"]','B','Digoxin and K+ compete for the same binding site on Na+/K+-ATPase. Hypokalemia reduces competition, increasing digoxin binding and toxicity at normal serum digoxin levels. Loop and thiazide diuretics commonly cause hypokalemia, predisposing to toxicity. A: Hyperkalemia protects (the opposite). C: Renal clearance is unaffected. D: Volume of distribution is not relevant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','mcq','Sacubitril/valsartan is used in HFrEF. Sacubitril inhibits neprilysin. What is the consequence?','["A. Increased breakdown of angiotensin II","B. Decreased natriuretic peptides (BNP, ANP)","C. Increased natriuretic peptides causing vasodilation and natriuresis","D. Inhibition of aldosterone synthesis"]','C','Neprilysin degrades natriuretic peptides (BNP, ANP). Sacubitril inhibits neprilysin, increasing BNP and ANP, promoting vasodilation, natriuresis, and diuresis. Combined with valsartan (ARB), it blocks the RAAS while enhancing natriuretic pathways. A: Neprilysin does not primarily degrade angiotensin II. B: Neprilysin inhibition increases natriuretic peptides. D: Aldosterone inhibition is from valsartan.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','mcq','A 65-year-old with HFrEF is started on spironolactone. Beyond diuresis, what additional benefit does spironolactone provide?','["A. Positive inotropic effect","B. Reduction of cardiac fibrosis and remodeling by blocking aldosterone","C. Rate control in atrial fibrillation","D. Bronchodilation improving exercise capacity"]','B','Aldosterone promotes cardiac fibrosis, myocyte hypertrophy, and adverse remodeling. Spironolactone blocks aldosterone receptors in the heart, reducing fibrosis and remodeling independently of diuresis, improving survival in HFrEF. A: Spironolactone has no inotropic effect. C: Rate control is a beta-blocker/CCB effect. D: Spironolactone does not affect bronchial tone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','mcq','Which beta-blocker approved for HFrEF also blocks alpha-1 receptors providing additional vasodilation?','["A. Metoprolol succinate","B. Atenolol","C. Carvedilol","D. Bisoprolol"]','C','Carvedilol is a non-selective beta-blocker that also blocks alpha-1 adrenergic receptors, providing vasodilation in addition to neurohormonal blockade. It is one of three beta-blockers with proven mortality benefit in HFrEF. A: Metoprolol succinate is beta-1 selective with no alpha-blocking. B: Atenolol lacks HF mortality data. D: Bisoprolol is beta-1 selective without alpha-blocking.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','mcq','Sublingual nitroglycerin provides rapid relief of acute angina through which primary mechanism?','["A. Blocking L-type calcium channels in coronary arteries","B. Releasing nitric oxide to cause coronary and venous vasodilation","C. Blocking beta-1 receptors to reduce myocardial oxygen demand","D. Inhibiting platelet aggregation in coronary vessels"]','B','Nitroglycerin converts to NO, activating guanylyl cyclase, increasing cGMP, relaxing vascular smooth muscle. Venodilation reduces preload; coronary dilation improves supply. A: CCB mechanism. C: Beta-blocker mechanism. D: Aspirin/antiplatelets mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','mcq','A patient on long-acting nitrates develops tolerance. Which strategy prevents nitrate tolerance?','["A. Providing a nitrate-free interval of 8-12 hours per day","B. Increasing the dose of nitrate","C. Combining with a diuretic","D. Switching to sublingual route only"]','A','Nitrate tolerance develops due to depletion of sulfhydryl groups. A daily nitrate-free interval allows repletion of sulfhydryl groups and prevents tolerance. A: Increasing dose worsens tolerance. C: Diuretics do not prevent tolerance. D: Sublingual nitroglycerin is for acute use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','mcq','Beta-blockers reduce myocardial oxygen demand in stable angina by which mechanism?','["A. Vasodilating coronary arteries","B. Reducing heart rate, contractility, and wall stress","C. Increasing coronary perfusion pressure","D. Blocking thromboxane A2 synthesis"]','B','Beta-blockers decrease heart rate (prolonging diastolic filling time) and reduce contractility and systolic wall stress — all reducing MVO2. A: Beta-blockers do not directly vasodilate coronaries. C: They may slightly reduce coronary perfusion pressure. D: Aspirin''''s mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','mcq','A 62-year-old with stable angina, COPD, and Raynaud''''s phenomenon needs antianginal therapy. Which agent is most appropriate?','["A. Propranolol","B. Atenolol","C. Amlodipine","D. Verapamil"]','C','Amlodipine (dihydropyridine CCB) is preferred when beta-blockers are contraindicated (COPD, Raynaud''''s). It causes coronary and peripheral vasodilation without bronchospasm. A: Propranolol is non-selective and contraindicated. B: Atenolol should be used cautiously in COPD. D: Diltiazem is an option but may cause more bradycardia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','mcq','Ranolazine is used as adjunct in stable angina. What is its unique mechanism?','["A. Inhibition of the late sodium current (late INa) in cardiac cells","B. Blockade of L-type calcium channels","C. Inhibition of the funny current (If) in the SA node","D. Nitric oxide release causing vasodilation"]','A','Ranolazine inhibits the late inward Na+ current (late INa) during ischemia, reducing intracellular Na+ and preventing Ca2+ overload via the Na+/Ca2+ exchanger. This reduces diastolic wall tension without affecting heart rate or BP. B: CCB mechanism. C: Ivabradine mechanism. D: Nitrate mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','mcq','A patient with Prinzmetal (vasospastic) angina has chest pain at rest and at night. Which drug is most appropriate?','["A. Isosorbide dinitrate or a calcium channel blocker","B. Propranolol","C. Ranolazine","D. Aspirin"]','A','Vasospastic angina is caused by coronary artery spasm. Nitrates and CCBs are drugs of choice as they relax coronary smooth muscle. A: Non-selective beta-blockers can paradoxically worsen vasospastic angina by allowing unopposed alpha-mediated coronary vasoconstriction. C: Ranolazine is not first-line for vasospastic angina. D: Aspirin does not relieve coronary spasm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','mcq','A patient with stable angina taking nitroglycerin presents with severe headache and hypotension after taking sildenafil. What is the mechanism?','["A. Both drugs increase cGMP: nitrates via NO, PDE-5 inhibitors by preventing cGMP breakdown, causing profound vasodilation","B. Both drugs inhibit platelet aggregation synergistically","C. Sildenafil inhibits CYP3A4, increasing nitroglycerin levels","D. PDE-5 inhibitors block nitrate metabolism in the liver"]','A','Nitrates increase cGMP via NO-mediated guanylyl cyclase activation. PDE-5 inhibitors prevent cGMP breakdown. Co-administration causes synergistic cGMP increase leading to profound systemic vasodilation and potentially fatal hypotension. This combination is absolutely contraindicated. A: Neither primarily affects platelets here. C: CYP3A4 inhibition is not the mechanism. D: PDE-5 inhibitors do not block nitrate metabolism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','mcq','A 70-year-old with stable angina and HFrEF (EF 35%) needs an antianginal. Which agent should be avoided?','["A. Long-acting nitrates","B. Ranolazine","C. Non-dihydropyridine CCBs (verapamil, diltiazem)","D. Beta-blockers"]','C','Non-dihydropyridine CCBs have significant negative inotropic effects that can decompensate HFrEF. They are contraindicated in systolic HF. Dihydropyridines (amlodipine, felodipine) are safer alternatives. A: Long-acting nitrates are useful in HF to reduce preload. C: Ranolazine does not worsen cardiac remodeling. D: Carvedilol, metoprolol succinate, and bisoprolol are indicated in stable HF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','mcq','Which hemodynamic change explains why nitrates can paradoxically increase myocardial oxygen demand when used alone?','["A. Reflex sympathetic activation causing tachycardia and increased contractility in response to hypotension","B. Direct coronary vasoconstriction","C. Increased preload through sodium retention","D. Increased afterload through peripheral vasoconstriction"]','A','Nitrate-induced venodilation and hypotension trigger baroreceptor-mediated reflex sympathetic activation, increasing heart rate and contractility, increasing MVO2. This is why combining nitrates with beta-blockers (which blunt reflex tachycardia) is rational. A: Nitrates vasodilate, not constrict. C: Nitrates reduce preload. D: Nitrates reduce afterload.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','mcq','Which correctly describes the mechanism by which calcium channel blockers relieve angina?','["A. They reduce MVO2 by decreasing heart rate and contractility, and improve supply by coronary vasodilation","B. They increase myocardial oxygen supply only by dilating coronary arteries","C. They block platelet aggregation in atherosclerotic coronary vessels","D. They inhibit late sodium current to reduce ischemic cell injury"]','A','CCBs (especially non-dihydropyridines) reduce heart rate and contractility (reducing MVO2) while also causing coronary vasodilation (increasing supply). Dihydropyridines primarily dilate coronary and peripheral vessels reducing afterload. A: CCBs also reduce MVO2; preload reduction is minimal. C: CCBs do not affect platelets. D: That is ranolazine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','mcq','Statins lower LDL cholesterol by inhibiting which rate-limiting enzyme in cholesterol biosynthesis?','["A. HMG-CoA reductase","B. Cholesterol 7-alpha-hydroxylase","C. Lipoprotein lipase","D. PCSK9"]','A','Statins competitively inhibit HMG-CoA reductase, the rate-limiting step in de novo cholesterol synthesis. This reduces intracellular cholesterol, upregulates LDL receptors, and increases LDL-C clearance. A: Cholesterol 7-alpha-hydroxylase is in bile acid synthesis. C: Lipoprotein lipase is the fibrate target. D: PCSK9 degrades LDL receptors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','mcq','A patient on simvastatin has markedly elevated CK and muscle aches. What is the most serious muscle-related adverse effect of statins?','["A. Myasthenia gravis","B. Myokymia","C. Peripheral neuropathy","D. Rhabdomyolysis"]','D','Rhabdomyolysis is the most serious statin muscle adverse effect — breakdown of skeletal muscle releasing myoglobin can cause AKI. Risk increased by gemfibrozil, azole antifungals, cyclosporine, CYP3A4 inhibitors. A: Statins do not cause myasthenia gravis. C: Peripheral neuropathy is rare. D: Myokymia is not a statin effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','mcq','Ezetimibe lowers cholesterol by which mechanism?','["A. Inhibiting the NPC1L1 transporter to block intestinal cholesterol absorption","B. Inhibiting HMG-CoA reductase in the liver","C. Binding bile acids in the gut to prevent reabsorption","D. Activating PPAR-alpha to increase lipoprotein lipase expression"]','A','Ezetimibe selectively inhibits the NPC1L1 transporter on intestinal enterocytes, blocking absorption of dietary and biliary cholesterol, reducing delivery to the liver and upregulating LDL receptors. A: That is the statin mechanism. C: Bile acid sequestrant mechanism. D: Fibrate mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','mcq','A 55-year-old with familial hypercholesterolemia on maximum statin + ezetimibe still has LDL-C of 180 mg/dL. Which agent provides the most additional LDL-C reduction?','["A. Gemfibrozil","B. Niacin","C. Alirocumab (PCSK9 inhibitor)","D. Cholestyramine"]','C','PCSK9 inhibitors (alirocumab, evolocumab) block PCSK9, preventing LDL receptor degradation and increasing LDL-C clearance. They reduce LDL-C by 50-70% on top of statin therapy. A: Fibrates primarily lower triglycerides. B: Niacin lowers LDL by 10-20%. D: Bile acid sequestrants have modest LDL-lowering.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','mcq','Gemfibrozil co-administered with simvastatin significantly increases rhabdomyolysis risk. What is the mechanism?','["A. Gemfibrozil activates CYP3A4, increasing simvastatin levels","B. Gemfibrozil increases simvastatin absorption from the gut","C. Both drugs competitively bind to HMG-CoA reductase","D. Gemfibrozil inhibits glucuronidation and biliary transport of simvastatin, increasing plasma levels"]','D','Gemfibrozil inhibits UGT (glucuronidation) and OATP1B1 transporter, reducing hepatic uptake and increasing systemic statin levels. This pharmacokinetic interaction markedly increases rhabdomyolysis risk. Gemfibrozil + simvastatin is contraindicated. A: Gemfibrozil inhibits, not activates, CYP enzymes. C: They act on different enzymes. D: Absorption is not the primary mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','mcq','A patient experiencing facial flushing after niacin asks how to minimize it. What is the best recommendation?','["A. Take niacin with grapefruit juice","B. Premedicate with aspirin 30 minutes before niacin","C. Take niacin on an empty stomach","D. Switch to an IV formulation"]','B','Niacin-induced flushing is mediated by prostaglandin D2 (PGD2) released from skin. Aspirin inhibits COX, blocking prostaglandin synthesis and reducing flushing. Taking aspirin 30 minutes before niacin is the standard recommendation. A: Grapefruit juice is relevant for statins, not niacin. C: Taking with food reduces GI effects, not flushing. D: IV niacin is not standard.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','mcq','A patient with severe hypertriglyceridemia (TG > 1000 mg/dL) is at risk for acute pancreatitis. Which drug class most effectively lowers triglycerides?','["A. Statins","B. PCSK9 inhibitors","C. Bile acid sequestrants","D. Fibrates"]','D','Fibrates (fenofibrate, gemfibrozil) activate PPAR-alpha, increasing lipoprotein lipase expression and decreasing VLDL production, effectively lowering TG by 20-50%. A: Statins primarily lower LDL-C with modest TG reduction. B: PCSK9 inhibitors primarily lower LDL-C. C: Bile acid sequestrants can raise TG and are contraindicated in hypertriglyceridemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','mcq','Which statin does NOT require CYP450 metabolism, making it less prone to drug interactions with CYP inhibitors?','["A. Simvastatin","B. Atorvastatin","C. Pravastatin","D. Lovastatin"]','C','Pravastatin is not significantly metabolized by CYP450 (it undergoes sulfation and other pathways), making it less susceptible to interactions with CYP3A4 inhibitors (e.g., azole antifungals, macrolides, HIV protease inhibitors). A: Simvastatin is a major CYP3A4 substrate. B: Atorvastatin is a CYP3A4 substrate. D: Lovastatin is a CYP3A4 prodrug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','mcq','Bile acid sequestrants can impair absorption of which important drugs?','["A. Metformin and insulin","B. Statins and fibrates","C. Beta-blockers and ACE inhibitors","D. Digoxin, warfarin, and thyroid hormone"]','D','Bile acid sequestrants are charged anion-exchange resins that non-specifically bind many drugs in the gut, reducing absorption. Digoxin, warfarin, and thyroid hormone have narrow therapeutic indices; their reduced absorption has significant consequences. Other drugs should be taken 1-2 h before or 4-6 h after the resin. A: Metformin and insulin are unaffected. C: Beta-blockers and ACE inhibitors are minimally affected. D: Not primarily bound by resins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','mcq','Statins are contraindicated during pregnancy. What is the primary reason?','["A. Statins cause maternal hypertension","B. Statins increase the risk of maternal thrombosis","C. Cholesterol is essential for fetal development; statins may cause fetal harm","D. Statins cause hepatotoxicity in the mother"]','C','Cholesterol is critical for fetal membrane synthesis, steroid hormone production, and myelination. Inhibiting cholesterol synthesis may cause fetal malformations. Statins are category X in pregnancy. A: Statins do not cause hypertension. C: Statins have antiplatelet pleiotropic effects. D: Hepatotoxicity is a maternal concern but not the teratogenic mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','mcq','Heparin exerts its anticoagulant effect primarily by binding to which endogenous protein?','["A. Protein C","B. Thrombomodulin","C. Vitamin K epoxide reductase","D. Antithrombin III"]','D','Heparin binds antithrombin III (ATIII), inducing a conformational change that accelerates ATIII-mediated inhibition of thrombin (factor IIa) and factor Xa approximately 1000-fold. A: Protein C is activated by thrombomodulin and degrades factors Va and VIIIa. C: Vitamin K epoxide reductase is inhibited by warfarin. D: Thrombomodulin activates protein C.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','mcq','Warfarin inhibits synthesis of which clotting factors?','["A. Factors II, VII, IX, and X (vitamin K-dependent factors)","B. Factors I, V, VIII, and X","C. Factors VIII, IX, and XI","D. Factor Xa and thrombin only"]','A','Warfarin inhibits vitamin K epoxide reductase, depleting reduced vitamin K required for gamma-carboxylation of clotting factors II, VII, IX, and X (and proteins C and S). A: Factor I and V are not vitamin K-dependent. C: Factor VIII is not vitamin K-dependent. D: Warfarin affects multiple factors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','mcq','Which agent is the specific reversal agent for dabigatran in severe bleeding?','["A. Protamine sulfate","B. Vitamin K","C. Idarucizumab","D. Andexanet alfa"]','C','Idarucizumab (Praxbind) is a humanized monoclonal antibody fragment that specifically binds dabigatran, neutralizing its anticoagulant effect within minutes. A: Protamine reverses heparin/LMWH. B: Vitamin K reverses warfarin. D: Andexanet alfa reverses factor Xa inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','mcq','A patient on heparin infusion develops platelet count drop from 280,000 to 60,000/μL on day 8 with a new DVT. What is the diagnosis and next step?','["A. HIT type 2; stop heparin and start argatroban","B. DIC; increase heparin dose","C. Drug-induced thrombocytopenia; switch to LMWH","D. Warfarin-induced skin necrosis; start vitamin K"]','A','This is classic HIT type 2 (immune-mediated): thrombocytopenia 5-10 days after heparin initiation with paradoxical thrombosis due to IgG antibodies against PF4-heparin complexes. Heparin must be stopped immediately; argatroban or other non-heparin anticoagulants are used. B: DIC does not cause thrombosis. C: LMWH is cross-reactive in HIT and contraindicated. D: Warfarin necrosis is unrelated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','mcq','A patient on warfarin has INR of 8.5 with minor gum bleeding and no life-threatening hemorrhage. What is the most appropriate management?','["A. Give IV protamine sulfate","B. Continue warfarin and increase monitoring","C. Give fresh frozen plasma immediately","D. Hold warfarin and give oral vitamin K"]','D','For elevated INR with minor bleeding, holding warfarin and administering oral vitamin K is appropriate. Oral vitamin K is effective within 24 hours and preferred over IV for non-life-threatening situations. A: Protamine reverses heparin, not warfarin. C: FFP is reserved for life-threatening bleeding. D: Continuing warfarin with supratherapeutic INR is dangerous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','mcq','Which property of LMWHs makes routine aPTT monitoring unnecessary compared to unfractionated heparin?','["A. LMWHs have more predictable pharmacokinetics with less protein binding","B. LMWHs have a shorter half-life","C. LMWHs do not require antithrombin III","D. LMWHs are given intravenously with fixed dosing"]','A','LMWHs bind fewer plasma proteins than unfractionated heparin, giving more predictable dose-response pharmacokinetics, allowing weight-based subcutaneous dosing without routine aPTT monitoring. Anti-Xa monitoring is used in renal impairment, obesity, and pregnancy. A: LMWHs have longer half-life (3-12 h) than UFH (~1.5 h). C: LMWHs still require ATIII. D: LMWHs are subcutaneous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','mcq','A 70-year-old with non-valvular AF and CrCl 28 mL/min needs anticoagulation. Which DOAC requires the most significant dose adjustment in severe renal impairment?','["A. Apixaban","B. Rivaroxaban","C. Dabigatran","D. Warfarin"]','C','Dabigatran is 80% eliminated unchanged by the kidneys. In severe renal impairment (CrCl < 30 mL/min), drug accumulates markedly, increasing bleeding risk; it is contraindicated in severe renal impairment. Apixaban has the lowest renal dependence (~27% renal elimination). A: Apixaban can be used with dose adjustment. B: Rivaroxaban requires dose adjustment. D: Warfarin is hepatically metabolized.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','mcq','A patient on warfarin is started on fluconazole (CYP2C9 inhibitor). What change in INR is expected?','["A. INR decreases; fluconazole induces warfarin metabolism","B. INR increases; fluconazole inhibits CYP2C9, reducing warfarin metabolism and increasing its effect","C. No change; warfarin is not metabolized by CYP2C9","D. INR decreases; fluconazole displaces warfarin from albumin"]','B','Warfarin is predominantly metabolized by CYP2C9. Fluconazole inhibits CYP2C9, reducing warfarin clearance and causing accumulation, increasing its anticoagulant effect and raising INR. A: Fluconazole is an inhibitor, not inducer. C: CYP2C9 is the primary warfarin metabolizing enzyme. D: Displacement would increase, not decrease, warfarin effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','mcq','Fondaparinux is a synthetic pentasaccharide. What is the key difference from LMWH regarding mechanism?','["A. Fondaparinux inhibits thrombin directly without ATIII","B. Fondaparinux blocks vitamin K-dependent factor synthesis","C. Fondaparinux inhibits both factor Xa and thrombin equally","D. Fondaparinux selectively inhibits factor Xa via ATIII, but does NOT inhibit thrombin"]','D','Fondaparinux binds antithrombin III and selectively inhibits factor Xa only. It is too short to simultaneously bind ATIII and thrombin (unlike UFH). It has no thrombin inhibitory activity. A: Fondaparinux requires ATIII. C: It does not inhibit thrombin. D: Fondaparinux does not affect vitamin K-dependent synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','mcq','Which anticoagulant is safe to use during pregnancy because it does not cross the placenta?','["A. Warfarin","B. Dabigatran","C. Heparin","D. Rivaroxaban"]','C','Heparin is a large, negatively charged glycosaminoglycan that cannot cross the placental barrier, making it safe for the fetus. It is the anticoagulant of choice in pregnancy. A: Warfarin crosses the placenta and is teratogenic. B: Dabigatran safety in pregnancy is unknown. D: Rivaroxaban is not recommended in pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','mcq','Aspirin inhibits platelet aggregation by irreversibly inhibiting which enzyme?','["A. COX-1 to block thromboxane A2 synthesis","B. COX-2 to block prostacyclin","C. Phosphodiesterase to increase cAMP in platelets","D. ADP P2Y12 receptors to block platelet activation"]','A','Aspirin irreversibly acetylates COX-1 in platelets, blocking TXA2 synthesis. TXA2 promotes platelet aggregation and vasoconstriction. Since platelets lack nuclei, they cannot synthesize new COX-1 (inhibition lasts 7-10 days). A: Inhibiting COX-2 blocks prostacyclin (antiplatelet);('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','mcq','Clopidogrel is a prodrug that requires activation by which enzyme system?','["A. CYP2D6","B. CYP2C19","C. CYP3A4","D. UGT1A1"]','B','Clopidogrel requires hepatic conversion by CYP2C19 to its active thiol metabolite, which irreversibly blocks the P2Y12 ADP receptor. CYP2C19 genetic polymorphisms (poor metabolizers) or inhibitors (e.g., omeprazole) reduce efficacy. A: CYP2D6 metabolizes beta-blockers, TCAs. C: CYP3A4 has a minor role. D: UGT1A1 glucuronidates bilirubin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','mcq','Ticagrelor differs from clopidogrel in that its P2Y12 receptor blockade is:','["A. Irreversible and requires hepatic activation","B. Reversible and requires renal activation","C. Irreversible and does not require hepatic activation","D. Reversible and does not require hepatic activation"]','D','Ticagrelor directly and reversibly binds P2Y12 without requiring hepatic bioactivation. This gives faster onset, greater antiplatelet effect, and effectiveness regardless of CYP2C19 genotype. A: Clopidogrel is irreversible; ticagrelor is reversible. C: Ticagrelor''''s blockade is reversible. D: Renal activation is not required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','mcq','A patient undergoing PCI for NSTEMI is given abciximab. What is its mechanism?','["A. Blocks COX-1 to prevent TXA2 synthesis","B. Blocks P2Y12 ADP receptor on platelets","C. Blocks GP IIb/IIIa receptor, preventing fibrinogen binding and platelet cross-linking","D. Inhibits phosphodiesterase to increase platelet cAMP"]','C','Abciximab is a chimeric monoclonal antibody fragment (Fab) that binds GP IIb/IIIa, blocking fibrinogen and von Willebrand factor binding, preventing the final common pathway of platelet aggregation. A: Aspirin mechanism. B: Clopidogrel/ticagrelor mechanism. D: Dipyridamole/cilostazol mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','mcq','A CYP2C19 poor metabolizer undergoes PCI with drug-eluting stent. Which antiplatelet should be preferred over clopidogrel?','["A. Aspirin","B. Dipyridamole","C. Ticagrelor or prasugrel","D. Abciximab"]','C','CYP2C19 poor metabolizers cannot adequately activate clopidogrel, resulting in increased stent thrombosis risk. Ticagrelor (direct-acting) and prasugrel (activated by CYP3A4/2B6, not 2C19) are preferred. A: Aspirin alone is insufficient post-PCI. B: Dipyridamole is not indicated post-PCI. D: Abciximab is peri-procedural IV, not for maintenance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','mcq','Ticagrelor carries a black-box warning regarding concomitant use with aspirin doses above 100 mg/day. Why?','["A. High-dose aspirin increases ticagrelor metabolism","B. High-dose aspirin inhibits prostacyclin","C. High-dose aspirin reduces the antiplatelet efficacy of ticagrelor","D. High-dose aspirin causes GI ulcers that interact with ticagrelor bleeding risk"]','C','High-dose aspirin (> 100 mg/day) reduces the efficacy of ticagrelor. It appears aspirin interferes with ticagrelor''''s antiplatelet effect, reducing its clinical benefit. Therefore, aspirin doses above 100 mg/day should be avoided with ticagrelor. A: Aspirin does not affect ticagrelor metabolism. B: Prostacyclin inhibition does not explain reduced ticagrelor efficacy. D: Combined GI bleeding risk is real but not the reason for this black-box warning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','mcq','A patient taking ibuprofen for arthritis also takes aspirin for cardiac protection. Why might ibuprofen interfere with aspirin''''s antiplatelet effect?','["A. Ibuprofen activates thromboxane A2 synthesis","B. Ibuprofen inhibits CYP2C9, increasing aspirin degradation","C. Ibuprofen (if taken before aspirin) competitively blocks aspirin''s access to the COX-1 serine acetylation site","D. Ibuprofen increases platelet production"]','C','Ibuprofen and aspirin both bind to the COX-1 active site. Ibuprofen binding is reversible and competitive; taken before aspirin, it sterically blocks access to serine 529 that aspirin acetylates, preventing irreversible COX-1 inactivation. Aspirin should be taken at least 60 minutes before ibuprofen. A: Ibuprofen inhibits TXA2 production. C: Aspirin metabolism is not CYP2C9-dependent. D: Platelets are not upregulated by ibuprofen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','mcq','Prasugrel is contraindicated in patients with a history of TIA or stroke. What is the main reason?','["A. Prasugrel has excess net harm (increased intracranial bleeding risk) in patients with prior TIA/stroke","B. Prasugrel causes severe QT prolongation in patients with prior CVA","C. Prasugrel activates CYP2C19 causing drug interactions in neurologic disease","D. Prasugrel causes TTP more commonly in stroke patients"]','A','TRITON-TIMI 38 trial showed patients with prior TIA/stroke who received prasugrel had no clinical benefit but excess risk of life-threatening intracranial hemorrhage, making this a contraindication. A: Prasugrel does not affect QT. C: Prasugrel is not activated by CYP2C19. D: TTP is not specific to stroke patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','mcq','Ticlopidine is rarely used today. What serious hematologic adverse effects limit its use?','["A. Aplastic anemia, agranulocytosis, and thrombotic thrombocytopenic purpura (TTP)","B. Hemolytic anemia from direct platelet toxicity","C. Iron-deficiency anemia from chronic GI bleeding","D. Megaloblastic anemia due to vitamin B12 deficiency"]','A','Ticlopidine is associated with life-threatening hematologic reactions including agranulocytosis, aplastic anemia, and TTP. These idiosyncratic reactions limit its use. Clopidogrel has a much lower incidence. B: Direct platelet toxicity is not the mechanism. C: GI bleeding is a general antiplatelet risk. D: Megaloblastic anemia is not a ticlopidine effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','mcq','Dipyridamole inhibits platelet aggregation by which mechanism?','["A. Inhibition of phosphodiesterase, increasing platelet cAMP","B. Irreversible COX-1 blockade","C. Blocking GP IIb/IIIa receptors","D. Irreversible P2Y12 ADP receptor blockade"]','A','Dipyridamole inhibits phosphodiesterase, preventing breakdown of cAMP in platelets, inhibiting platelet activation. It also may potentiate prostacyclin. Used in combination with aspirin for stroke prevention. A: Irreversible COX-1 blockade is aspirin. C: GP IIb/IIIa blockade is abciximab/eptifibatide. D: Irreversible P2Y12 blockade is clopidogrel/prasugrel.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','mcq','Alteplase (tPA) acts as a thrombolytic by which mechanism?','["A. Converting plasminogen to plasmin, which degrades fibrin clots","B. Directly cleaving fibrin in clots","C. Inhibiting thrombin to prevent further clot formation","D. Blocking GP IIb/IIIa to dissolve existing clots"]','A','Alteplase (tPA) preferentially activates plasminogen bound to fibrin within clots, converting it to plasmin, which then degrades fibrin. A: tPA does not directly cleave fibrin. C: tPA does not inhibit thrombin. D: GP IIb/IIIa inhibition prevents new clot formation, not dissolution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','mcq','A patient presents with STEMI 2 hours after onset and no PCI is available within 90 minutes. Which thrombolytic is most commonly used?','["A. Streptokinase","B. Alteplase (tPA)","C. Warfarin","D. Heparin"]','B','Alteplase (tPA) is the preferred fibrin-specific thrombolytic for STEMI when primary PCI is not available in the recommended time window. It is more fibrin-specific and effective than streptokinase. A: Streptokinase is less fibrin-specific and antigenic. C: Warfarin is an anticoagulant, not a thrombolytic. D: Heparin prevents further clot formation but does not dissolve clots.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','mcq','Which of the following is an absolute contraindication to thrombolytic therapy?','["A. Age over 75 years","B. Use of aspirin within 7 days","C. Poorly controlled hypertension (BP 160/100)","D. Prior hemorrhagic stroke at any time"]','D','Prior hemorrhagic stroke is an absolute contraindication to thrombolytics due to very high risk of recurrent intracranial hemorrhage. A: Advanced age is a relative contraindication. C: Severely uncontrolled hypertension (>180/110) is relative; 160/100 is not absolute. D: Aspirin use is not a contraindication.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','mcq','Streptokinase is antigenic. What clinical consequence does this have?','["A. Patients previously treated with streptokinase may develop antibodies reducing efficacy or causing allergic reactions on re-exposure","B. Streptokinase causes more intracranial bleeding than tPA","C. Streptokinase requires CYP3A4 metabolism before activation","D. Streptokinase is contraindicated in all patients with prior MI"]','A','Streptokinase is a bacterial protein derived from streptococci. Prior exposure generates neutralizing antibodies, reducing efficacy. Repeat administration should be avoided for at least 6-12 months to prevent anaphylaxis. A: Both agents carry similar intracranial bleeding risk. C: Streptokinase is not metabolized by CYP enzymes. D: Prior MI is not a contraindication per se.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','mcq','A 55-year-old man presents with acute ischemic stroke 3 hours after symptom onset. What is the recommended pharmacologic treatment?','["A. IV alteplase within 4.5 hours of symptom onset","B. Warfarin loading dose","C. Heparin infusion to prevent extension","D. Aspirin 325 mg only"]','A','IV alteplase (tPA) is the only FDA-approved thrombolytic for acute ischemic stroke within 4.5 hours of symptom onset. It improves functional outcomes by restoring cerebral perfusion. A: Warfarin is not used acutely. C: Heparin does not lyse established clots. D: Aspirin alone is insufficient within the thrombolytic window.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','mcq','Tenecteplase differs from alteplase in what pharmacokinetic advantage?','["A. Longer half-life allowing single IV bolus administration","B. Oral bioavailability for chronic use","C. Not fibrin-specific, enabling broader plasminogen activation","D. Requires co-administration with streptokinase for activation"]','A','Tenecteplase (TNK-tPA) has a longer half-life (~20 minutes vs ~5 minutes for alteplase) and higher fibrin specificity, allowing single IV bolus dosing rather than infusion, simplifying administration in STEMI. B: No thrombolytic has oral bioavailability. C: Tenecteplase is more fibrin-specific. D: Tenecteplase is a standalone agent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','mcq','A patient who received thrombolytic therapy for STEMI develops life-threatening intracranial hemorrhage. What agent can partially reverse the fibrinolytic state?','["A. Vitamin K","B. Protamine sulfate","C. Aminocaproic acid (antifibrinolytic)","D. Idarucizumab"]','C','Aminocaproic acid and tranexamic acid are antifibrinolytics that competitively inhibit plasminogen activation, halting fibrinolysis. They can treat hemorrhagic complications of thrombolytic therapy, along with cryoprecipitate to replace fibrinogen. A: Vitamin K reverses warfarin. B: Protamine reverses heparin. D: Idarucizumab reverses dabigatran.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','mcq','Which best explains why tPA is more fibrin-specific than streptokinase?','["A. tPA can only be administered intravenously while streptokinase is oral","B. tPA preferentially activates plasminogen bound to fibrin within clots; streptokinase activates circulating plasminogen systemically","C. tPA has a longer half-life and remains active only at clot sites","D. tPA directly inhibits thrombin rather than activating plasmin"]','B','tPA has a high affinity for fibrin-bound plasminogen, forming a ternary complex with fibrin and plasminogen, activating plasmin locally within the clot. Streptokinase forms a complex with free circulating plasminogen systemically causing a lytic state and degrading circulating clotting factors. A: Both are given IV. C: Half-life does not determine fibrin specificity. D: tPA works via plasmin, not thrombin inhibition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','mcq','A 65-year-old woman with known aortic dissection presents with severe chest pain. Why are thrombolytics absolutely contraindicated?','["A. Thrombolytics cause acute kidney injury in aortic dissection","B. Aortic dissection is a venous thromboembolism and thrombolytics are only approved for arterial thrombosis","C. Thrombolytics interact with beta-blockers used to treat aortic dissection","D. Thrombolytics would lyse the protective clot at the dissection tear, worsening hemorrhage and extending the dissection"]','D','In aortic dissection, the false lumen is partially sealed by thrombus. Administering thrombolytics would lyse this hemostatic clot, allowing uncontrolled hemorrhage into the pericardium or mediastinum, potentially causing fatal tamponade or extending the dissection. A: Renal clearance is not the concern. C: No pharmacokinetic interaction. D: Thrombolytics are used for various thrombotic conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','mcq','What is the primary risk of thrombolytic therapy that must be weighed against its benefit?','["A. Risk of severe allergic anaphylaxis","B. Risk of acute liver failure","C. Risk of QT prolongation and torsades de pointes","D. Risk of serious hemorrhage, including intracranial bleeding"]','D','The principal risk of thrombolytics is serious hemorrhage — most critically intracranial hemorrhage — because systemic fibrinolysis breaks down clots throughout the body. A: Allergic reactions occur with streptokinase but are not the primary risk for all thrombolytics. C: Thrombolytics do not cause QT prolongation. D: Hepatotoxicity is not a thrombolytic concern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','mcq','Sildenafil is used in PAH. What is its mechanism?','["A. Blocks endothelin receptors to reduce pulmonary vasoconstriction","B. Is a prostacyclin analogue that directly activates IP receptors","C. Inhibits PDE-5 to increase cGMP, causing pulmonary vasodilation","D. Activates beta-2 receptors to dilate pulmonary vessels"]','C','Sildenafil inhibits PDE-5, highly expressed in pulmonary vascular smooth muscle. PDE-5 normally degrades cGMP; its inhibition increases cGMP, activating protein kinase G and causing pulmonary vasodilation and reduced right ventricular afterload. A: ET receptor antagonism is bosentan/ambrisentan. C: Epoprostenol/iloprost mechanism. D: Beta-2 agonists are used in asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','mcq','Bosentan is an endothelin receptor antagonist used in PAH. Endothelin-1 normally causes which effect on pulmonary vasculature?','["A. Vasodilation and reduced smooth muscle proliferation","B. Vasoconstriction and smooth muscle proliferation","C. Increased nitric oxide production","D. Decreased right ventricular afterload"]','B','Endothelin-1 (ET-1) is a potent vasoconstrictor. It binds ET-A and ET-B receptors on vascular smooth muscle, causing sustained vasoconstriction and pulmonary vascular remodeling (smooth muscle proliferation). Bosentan blocks both receptors. A: ET-1 causes the opposite. C: ET-1 does not increase NO. D: ET-1 increases, not decreases, right ventricular afterload.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','mcq','Epoprostenol must be given by continuous IV infusion. Why?','["A. It has a very short half-life of approximately 3-5 minutes","B. It is poorly absorbed from the GI tract","C. It causes tachyphylaxis within hours","D. It is metabolized by the liver within 30 minutes"]','A','Epoprostenol (prostacyclin) has an extremely short plasma half-life of 3-5 minutes because it is rapidly hydrolyzed in the blood and tissues. Continuous IV infusion via central venous catheter is necessary. Central line failure can cause rebound fatal pulmonary hypertension. B: It is not given orally. C: Tachyphylaxis is a dose-related tolerance issue. D: Hepatic metabolism is not the reason.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','mcq','A patient with PAH is started on bosentan. What monitoring is required due to a known adverse effect?','["A. Monthly serum creatinine for nephrotoxicity","B. Daily INR monitoring","C. Weekly platelet counts for thrombocytopenia","D. Monthly liver function tests for hepatotoxicity"]','D','Bosentan can cause dose-dependent hepatotoxicity with elevated liver enzymes. Monthly LFT monitoring is mandatory. Bosentan is also a potent CYP3A4 and CYP2C9 inducer, reducing the efficacy of many drugs including contraceptives. A: Nephrotoxicity is not a primary bosentan concern. C: Thrombocytopenia is not characteristically associated. D: Bosentan does not require daily INR monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','mcq','Which prostacyclin analogue for PAH can be administered by inhalation?','["A. Ambrisentan","B. Treprostinil","C. Iloprost","D. Riociguat"]','C','Iloprost is a stable prostacyclin analogue that can be administered by inhalation (inhaled form: Ventavis), selectively delivering the drug to the pulmonary vasculature. It has a longer half-life than epoprostenol (20-30 minutes). A: Ambrisentan is an ET receptor antagonist. B: Treprostinil can be inhaled but iloprost was the first approved inhaled prostanoid. D: Riociguat is a soluble guanylyl cyclase stimulator.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','mcq','Riociguat is used for PAH and CTEPH. What is its mechanism?','["A. Inhibits PDE-5 to prevent cGMP breakdown","B. Activates prostacyclin receptors (IP receptors) on smooth muscle","C. Blocks ET-A receptors only in the pulmonary circulation","D. Directly stimulates soluble guanylyl cyclase to produce cGMP independently and in synergy with NO"]','D','Riociguat directly stimulates soluble guanylyl cyclase (sGC), increasing cGMP both independently and by sensitizing sGC to endogenous NO. Distinct from PDE-5 inhibitors that prevent cGMP breakdown. Riociguat is the only drug approved for CTEPH. A: That is sildenafil''''s mechanism. C: ET receptor antagonism is bosentan/ambrisentan. D: IP receptor activation is the prostacyclin mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','mcq','Riociguat is absolutely contraindicated with PDE-5 inhibitors. What is the reason?','["A. Both drugs cause tachycardia that is additive in PAH","B. Both drugs cause hepatotoxicity when combined","C. Riociguat inhibits the metabolism of sildenafil","D. Both drugs increase cGMP (riociguat by producing more; PDE-5 inhibitors by preventing breakdown), causing profound hypotension"]','D','Riociguat increases cGMP by stimulating guanylyl cyclase; PDE-5 inhibitors prevent cGMP degradation. Together, cGMP accumulates excessively, causing profound systemic hypotension. This combination is absolutely contraindicated. A: Tachycardia is not the primary concern. C: Riociguat does not inhibit sildenafil metabolism. D: Hepatotoxicity is not the reason.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','mcq','Ambrisentan is a selective ET-A receptor antagonist, while bosentan blocks both ET-A and ET-B. What is the theoretical advantage of ET-A selectivity?','["A. ET-A blockade reduces vasoconstriction while preserving ET-B-mediated endothelial NO release","B. ET-A selectivity causes more potent hepatotoxicity","C. Blocking ET-B would increase pulmonary vasoconstriction","D. ET-A selective agents have a longer half-life"]','A','ET-B receptors on endothelial cells mediate release of NO and prostacyclin (vasodilatory). Selective ET-A blockade reduces vasoconstriction and smooth muscle proliferation while preserving ET-B-mediated vasodilation. B: Ambrisentan actually has less hepatotoxicity than bosentan. C: ET-B on smooth muscle causes vasoconstriction, but endothelial ET-B causes vasodilation. D: Half-life differences are not the clinical rationale.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','mcq','A 35-year-old woman of childbearing age is started on bosentan for PAH. What mandatory reproductive safety measure must be implemented?','["A. Male partners must use condoms","B. Delay treatment until after menopause","C. Periodic pregnancy testing only","D. Two effective non-hormonal contraceptive methods required (bosentan is teratogenic and induces hormonal contraceptive metabolism)"]','D','Bosentan is teratogenic (Category X) and induces CYP3A4/CYP2C9, significantly reducing hormonal contraceptive efficacy. Women must use two reliable non-hormonal contraceptive methods simultaneously, with monthly pregnancy testing under REMS. A: Male partner measures are insufficient. C: Testing alone without contraception is insufficient. D: Treatment should not be delayed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','mcq','Tadalafil differs from sildenafil for PAH treatment primarily in its:','["A. Mechanism of action (tadalafil blocks ET receptors)","B. Longer half-life allowing once-daily dosing","C. Route of administration (tadalafil is inhaled)","D. Primary indication for ventricular arrhythmias in PAH"]','B','Tadalafil is a PDE-5 inhibitor like sildenafil but has a much longer half-life (~17.5 hours vs ~4 hours for sildenafil), enabling once-daily dosing and improving adherence. Both drugs reduce pulmonary vascular resistance via cGMP. A: Both are PDE-5 inhibitors, not ET antagonists. C: Both are oral tablets. D: PDE-5 inhibitors are not used for arrhythmias.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','mcq','A patient on warfarin starts rifampicin for tuberculosis. What change in warfarin dose is expected and why?','["A. Decrease dose; rifampicin inhibits CYP2C9, increasing warfarin levels","B. Decrease dose; rifampicin displaces warfarin from plasma proteins","C. No change; rifampicin does not interact with warfarin","D. Increase dose; rifampicin induces CYP2C9/3A4, increasing warfarin metabolism and reducing its effect"]','D','Rifampicin is a potent CYP2C9 and CYP3A4 inducer, significantly increasing warfarin metabolism and dramatically reducing its anticoagulant effect, requiring substantial dose increase to maintain therapeutic INR. A: The effect is opposite. C: This is a major drug interaction. D: Displacement would increase warfarin effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','mcq','A patient on digoxin is prescribed amiodarone. What effect does amiodarone have on digoxin levels?','["A. Amiodarone decreases digoxin levels by inducing renal excretion","B. Amiodarone increases digoxin levels by inhibiting P-glycoprotein and reducing renal clearance","C. Amiodarone has no clinically significant effect on digoxin","D. Amiodarone decreases digoxin levels by inducing CYP3A4"]','B','Amiodarone inhibits P-glycoprotein (P-gp), which secretes digoxin into the renal tubule. Blocking P-gp reduces digoxin renal elimination, increasing digoxin serum levels and risk of toxicity. Digoxin dose should be reduced by ~50% when amiodarone is initiated. A: The opposite occurs. C: This is a clinically important interaction. D: Amiodarone inhibits, not induces, CYP enzymes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','mcq','ACE inhibitors and potassium-sparing diuretics (e.g., spironolactone) co-administered can cause which serious electrolyte adverse effect?','["A. Hyperkalemia","B. Hypokalemia","C. Hyponatremia","D. Hypermagnesemia"]','A','ACE inhibitors reduce aldosterone, decreasing potassium excretion. Spironolactone further blocks aldosterone receptors, reducing potassium excretion. The combination can cause life-threatening hyperkalemia. Serum potassium must be monitored closely. A: Hypokalemia is the opposite. C: Hyponatremia is less concerning. D: Hypermagnesemia is not a consequence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','mcq','A diabetic patient on metformin has contrast CT and is also on furosemide. Which adverse effect is potentiated?','["A. Metformin-induced lactic acidosis due to contrast-induced nephropathy reducing metformin clearance","B. Hypoglycemia from furosemide enhancing metformin effects","C. Hypertension from furosemide-induced volume depletion","D. Photosensitivity from combined furosemide and contrast dye"]','A','Furosemide can cause volume depletion and reduced renal perfusion. Contrast nephropathy further impairs renal function. Metformin is renally excreted; if renal function declines, it accumulates — increasing risk of potentially fatal lactic acidosis. Metformin should be held before and after contrast if renal function is compromised. B: Furosemide does not enhance metformin''''s glucose-lowering. C: This is not a recognized interaction. D: Not a recognized interaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','mcq','A patient on clopidogrel is prescribed omeprazole for GI protection. Why does this interaction reduce clopidogrel efficacy?','["A. Omeprazole accelerates clopidogrel excretion via renal pathways","B. Omeprazole induces CYP3A4, causing more rapid clopidogrel metabolism to inactive compounds","C. Omeprazole directly competes with clopidogrel at the P2Y12 receptor","D. Omeprazole inhibits CYP2C19, reducing hepatic activation of clopidogrel to its active metabolite"]','D','Clopidogrel requires CYP2C19 for bioactivation. Omeprazole and esomeprazole are potent CYP2C19 inhibitors, reducing conversion to active metabolite and reducing antiplatelet efficacy. Pantoprazole (weaker CYP2C19 inhibitor) or H2 blockers are preferred. A: Renal excretion is not affected. C: Omeprazole does not compete at P2Y12. D: Omeprazole inhibits, not induces, CYP enzymes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','mcq','A patient on verapamil is started on metoprolol for rate control. What cardiovascular adverse effect is most likely?','["A. Hypertension from combined vasoconstriction","B. Severe bradycardia or heart block from additive depression of AV nodal conduction","C. Hypokalemia from combined potassium wasting","D. QT prolongation from additive sodium channel blockade"]','B','Both verapamil (Class IV) and metoprolol (Class II, beta-blocker) slow AV nodal conduction. Combined, they have additive negative dromotropic effects causing severe bradycardia, high-degree AV block, or asystole. A: Both drugs lower blood pressure; combination causes hypotension. C: Neither primarily affects potassium. D: Neither significantly blocks sodium channels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','mcq','A HF patient on lisinopril, spironolactone, and carvedilol is started on an NSAID for arthritis. Which adverse effect of NSAIDs is most problematic?','["A. NSAIDs cause bronchospasm worsening dyspnea","B. NSAIDs reduce renal prostaglandins, causing sodium retention, worsening hypertension and HF, and reducing ACEI/diuretic efficacy","C. NSAIDs block aldosterone, compounding spironolactone effects","D. NSAIDs accelerate digoxin clearance"]','B','NSAIDs inhibit renal prostaglandins (PGE2, PGI2) that maintain renal blood flow and promote natriuresis. In HF with compromised renal perfusion, NSAIDs cause sodium and water retention, worsening HF and hypertension, and blunt ACE inhibitor and diuretic efficacy. A: NSAID-associated bronchospasm is mainly in aspirin-sensitive asthma. C: NSAIDs do not block aldosterone. D: NSAIDs do not affect digoxin clearance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','mcq','A patient on simvastatin 80 mg is prescribed clarithromycin. What serious drug interaction should the prescriber anticipate?','["A. Clarithromycin reduces simvastatin absorption from the gut","B. Clarithromycin inhibits CYP3A4, markedly increasing simvastatin plasma levels and risk of rhabdomyolysis","C. Simvastatin induces clarithromycin metabolism, reducing antibiotic efficacy","D. Combined use causes additive QT prolongation"]','B','Simvastatin is metabolized by CYP3A4. Clarithromycin is a potent CYP3A4 inhibitor; co-administration causes markedly elevated plasma statin levels and a substantial increase in rhabdomyolysis risk. Simvastatin should be withheld during clarithromycin therapy. A: The interaction is metabolic. C: Simvastatin does not induce CYP enzymes. D: QT prolongation is from clarithromycin alone; not the primary statin interaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','mcq','A patient with AF on warfarin self-medicates with St. John''''s Wort. Her INR drops from 2.5 to 1.4. What is the mechanism?','["A. St. John''s Wort chelates warfarin in the gut, reducing absorption","B. St. John''s Wort induces CYP2C9 and P-glycoprotein, increasing warfarin metabolism and reducing plasma levels","C. St. John''s Wort inhibits CYP2C9, decreasing warfarin metabolism","D. St. John''s Wort displaces warfarin from plasma albumin"]','B','St. John''''s Wort is a potent inducer of CYP2C9, CYP3A4, and P-glycoprotein. Induction of CYP2C9 accelerates warfarin metabolism, reducing its plasma concentration and anticoagulant effect. A: Chelation/absorption reduction is not the mechanism. C: The effect is induction, not inhibition. D: Displacement from albumin would increase warfarin effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','mcq','Which cardiovascular drug class is associated with first-dose orthostatic hypotension?','["A. Beta-blockers","B. ACE inhibitors","C. Alpha-1 blockers (e.g., doxazosin, prazosin)","D. Thiazide diuretics"]','C','Alpha-1 adrenergic blockers (prazosin, doxazosin) block peripheral alpha-1 receptors, preventing norepinephrine-mediated vasoconstriction. The first dose can cause dramatic vasodilation with orthostatic hypotension, dizziness, and syncope (first-dose effect). Patients should take the first dose at bedtime. A: Beta-blockers cause bradycardia/fatigue. B: ACE inhibitors can cause hypotension, especially in volume-depleted patients. D: Thiazides cause gradual BP reduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');